// Changes stored by released versions describe exactly as they did then. The fixtures in
// test/compat were generated by running each release's own code (its git tag) over the golden
// fixtures, the real-record scenarios and a few edge cases, and are never regenerated.
import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import { test } from 'node:test';
import { describe, type Change } from '../../src/index.ts';

const dir = new URL('../compat/', import.meta.url);
const variants: Record<string, object> = { default: {}, 'en-IN Asia/Kolkata': { locale: 'en-IN', timeZone: 'Asia/Kolkata' } };

interface Stored {
  version: string;
  cases: { name: string; changes: Change[]; sentences: Record<string, string[]> }[];
}

const files = readdirSync(dir).filter((f) => f.endsWith('.json'));

test('there are stored changes from 1.0 and 1.1', () => {
  assert.deepEqual(files, ['stored-1.0.1.json', 'stored-1.1.0.json']);
});

for (const file of files) {
  const stored: Stored = JSON.parse(readFileSync(new URL(file, dir), 'utf8'));
  test(`changes stored by ${stored.version} describe exactly as before`, () => {
    assert.ok(stored.cases.length >= 30);
    for (const c of stored.cases) {
      for (const [variant, options] of Object.entries(variants)) {
        assert.deepEqual(describe(c.changes, options).map((s) => s.text), c.sentences[variant], `${c.name} (${variant})`);
      }
    }
  });
}
